async function request(path:string, options:RequestInit={}, token?:string){
  const response=await fetch(`${apiBase}${path}`,{...options,headers:{'Content-Type':'application/json',apikey:publicAnonKey,Authorization:`Bearer ${token||publicAnonKey}`,...options.headers}})
  const data=await response.json().catch(()=>({error:'Unexpected server response.'}))
  if(!response.ok)throw new ApiError(data.error||'Request failed.',response.status)
  return data
}

type OfflineOperation={id:string;userId:string;path:string;options:RequestInit;createdAt:string}
function offlineDb():Promise<IDBDatabase>{return new Promise((resolve,reject)=>{const req=indexedDB.open('kaijage-pos-offline',1);req.onupgradeneeded=()=>{const db=req.result;if(!db.objectStoreNames.contains('snapshots'))db.createObjectStore('snapshots');if(!db.objectStoreNames.contains('outbox'))db.createObjectStore('outbox',{keyPath:'id'})};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
function offlineCryptoKey():Promise<CryptoKey>{let encoded=localStorage.getItem('kaijage-offline-key');if(!encoded){const bytes=crypto.getRandomValues(new Uint8Array(32));encoded=btoa(String.fromCharCode(...bytes));localStorage.setItem('kaijage-offline-key',encoded)}const bytes=Uint8Array.from(atob(encoded),c=>c.charCodeAt(0));return crypto.subtle.importKey('raw',bytes,{name:'AES-GCM'},false,['encrypt','decrypt'])}
async function encryptOffline(value:any){const iv=crypto.getRandomValues(new Uint8Array(12));const key=await offlineCryptoKey();const data=new TextEncoder().encode(JSON.stringify(value));const payload=await crypto.subtle.encrypt({name:'AES-GCM',iv},key,data);return {iv,payload}}
async function decryptOffline<T>(entry:any):Promise<T|undefined>{if(!entry?.payload||!entry?.iv)return undefined;const key=await offlineCryptoKey();const bytes=await crypto.subtle.decrypt({name:'AES-GCM',iv:entry.iv},key,entry.payload);return JSON.parse(new TextDecoder().decode(bytes)) as T}
async function offlineRead<T>(store:string,key:IDBValidKey):Promise<T|undefined>{const db=await offlineDb();return new Promise((resolve,reject)=>{const req=db.transaction(store,'readonly').objectStore(store).get(key);req.onsuccess=()=>{void decryptOffline<T>(req.result).then(resolve,reject)};req.onerror=()=>reject(req.error)})}
async function offlineWrite(store:string,value:any,key?:IDBValidKey){const encrypted=await encryptOffline(value);const db=await offlineDb();return new Promise<void>((resolve,reject)=>{const tx=db.transaction(store,'readwrite');if(store==='outbox')tx.objectStore(store).put({id:value.id,...encrypted});else tx.objectStore(store).put(encrypted,key);tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error)})}
async function offlineOutbox(userId:string):Promise<OfflineOperation[]>{const db=await offlineDb();const entries=await new Promise<any[]>((resolve,reject)=>{const req=db.transaction('outbox','readonly').objectStore('outbox').getAll();req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});const operations=await Promise.all(entries.map(entry=>decryptOffline<OfflineOperation>(entry)));return operations.filter((x):x is OfflineOperation=>Boolean(x&&x.userId===userId)).sort((a,b)=>a.createdAt.localeCompare(b.createdAt))}
async function offlineRemove(id:string){const db=await offlineDb();return new Promise<void>((resolve,reject)=>{const tx=db.transaction('outbox','readwrite');tx.objectStore('outbox').delete(id);tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error)})}

